(function(){
'use strict';
const E=window.AudienceEngine,KEY='utup.audience.demo.v1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles=['任务创建','需求理解','策略确认','条件构建','执行评估','资产沉淀'];
const outputs=['任务卡','需求理解单','人群策略卡','执行条件单','人群包 / 评估报告','策略档案'];
let executionTab='audience',draftQuery='',draftPlatform='',artifactView=null,workflowBusy=false;
const labels={object:'目标人群 / 业务对象',action:'目标行为与使用意图',window:'时间窗口（天）',domain:'业务域',definition:'关键概念口径',platform:'生效平台 / 使用入口',exclude:'排除条件',success:'成功标准',experiment:'实验 ID 与目标指标'};
const hints={object:'例如：同时具备出游意向和住宿偏好的用户',action:'例如：召回、复购、品牌触达',window:'“近期”需要明确为具体天数',domain:'生服 或 跨域；LDMP 仅生服',definition:'明确兴趣信号、消费分层或价格带的判断口径',platform:'例如：生服运营入口',exclude:'明确排除对象，或填写无额外排除',success:'例如：得到可供业务抽检的人群包；不预填收益',experiment:'演示实验标识和指标，例如 DEMO-EXP-01 / 核销'};
let host,options={},tasks=[],active=null,view='home',scope='portal',picked=new Set(['balanced']),upload=[],seedAsset=null,message='',runFailure='',running=false,compareVersion=null;
try{tasks=JSON.parse(localStorage.getItem(KEY)||'[]').filter(t=>t.schema===1);}catch(e){tasks=[];}
const current=()=>tasks.find(t=>t.id===active);
const button=(text,act,cls='',disabled=false,extra='')=>`<button type="button" class="${cls}" data-action="${act}" ${disabled?'disabled':''} ${extra}>${text}</button>`;
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(tasks));}catch(e){message='浏览器存储不可用，任务仅保留在本次页面中';}}
function notify(s){message=s;render();setTimeout(()=>{if(message===s){message='';const n=host?.querySelector('.toast');if(n)n.remove();}},3500);}
function needTask(){const t=current();if(!t)throw Error('请先创建任务');return t;}
function state(t){if(t.invalid)return '已失效';if(t.blocker)return '受阻';if(t.archived)return '已归档';if(t.result?.approved)return '待归档';if(t.attempts>=3)return '转人工处理';if(t.stage===3)return E.validation(t).length?'需处理缺口':'条件就绪';if(t.stage===4&&!t.result)return running?'执行中':'待执行';return ['已创建','待补充','方案待确认','待执行','结果待复核','策略档案'][t.stage];}
function mount(node,opts={}){host=node;options=opts;try{tasks=JSON.parse(localStorage.getItem(KEY)||'[]').filter(t=>t.schema===1);}catch(e){}view=opts.view||'home';if(view==='home'&&opts.resume&&current())view='task';for(const task of tasks){E.cancelActivity(task,'页面重新打开，上次未完成的处理已中断');for(const h of task.handoffs||[])if(['prepared','running'].includes(h.status))h.status='cancelled';}persist();host.classList.add('aud');render();}
function render(){if(!host||!host.isConnected)return;const t=current(),scrolls=[...host.querySelectorAll('.aud-column-content')].map(n=>n.scrollTop),canvasKey=active+':'+(artifactView!==null?'artifact-'+artifactView:t?.stage),sameTask=host.dataset.task===active,sameCanvas=host.dataset.canvas===canvasKey;host.dataset.task=active||'';host.dataset.canvas=canvasKey;host.classList.toggle('is-home',view==='home');host.classList.toggle('is-task',view==='task');host.innerHTML=`<header class="head between"><div class="studio-brand"><span class="brand-icon">✦</span><div><h1>${view==='archive'?'人群与策略':'圈人 Agent'}</h1><p>智能圈选工作台</p></div></div><div class="task-meta">${view==='task'&&t?`<span>${esc(t.id)}</span>${badge(state(t),t.blocker?'amber':'green')}<b>V${t.version}</b>`:''}</div><div class="row"><details class="aud-demo-note"><summary>演示版</summary><p>当前使用模拟资产与执行结果，尚未接入真实模型、数据服务和投放平台。任务仅保存在当前浏览器。</p></details>${button('历史任务','archives','quiet')}${button('＋ 新建任务','home','small')}</div></header>${view==='home'?home():view==='archive'?archives():t?workspace(t):home()}${message?`<div role="status" class="toast">${esc(message)}</div>`:''}`;bind();if(sameTask)host.querySelectorAll('.aud-column-content').forEach((n,i)=>{if(i!==1||sameCanvas)n.scrollTop=scrolls[i]||0;});}
function section(title,subtitle,body,extra=''){return `<section class="work-card"><div class="work-card-title between"><div><h3>${title}</h3>${subtitle?`<p class="muted">${subtitle}</p>`:''}</div>${extra}</div><div class="work-card-body">${body}</div></section>`;}
function roles(){return `<div class="aud-agent-role"><span class="agent-avatar">圈</span><div><b>圈人 Agent</b><p>理解目标、提出策略、匹配资产、把关与解释结果</p></div></div><div class="agent-connector">执行条件与版本 ↓　↑ SQL、结果或缺口</div><div class="aud-agent-role"><span class="agent-avatar secondary">理</span><div><b>用户理解 Agent</b><p>接收结构化条件，生成查询并返回执行回执</p></div></div>`;}
function artifactAvailability(t){return [true,true,t.confirmed,t.conditions.length>0,!!t.result,t.archived];}
function activityCard(t,a){const stateNames={running:'正在处理',done:'已完成',waiting:'等待业务补充',blocked:'已阻断',cancelled:'已中断'};return `<section class="agent-activity ${a.status}" aria-label="${esc(a.title)}"><div class="between"><h3><span class="${a.status==='running'?'activity-spinner':'activity-dot'}"></span>${esc(a.status==='running'?a.title:a.title.replace('正在',' · '))}</h3>${badge(stateNames[a.status]||'待开始',a.status==='blocked'||a.status==='waiting'?'amber':a.status==='done'?'green':'')}</div><p class="activity-meta">本地流程演示 · V${a.version} · ${esc(a.started.slice(11,19))}</p><ol class="agent-todos">${a.items.map((item,i)=>`<li class="todo-${item.status}"><span class="todo-symbol">${item.status==='done'?'✓':item.status==='blocked'?'!':item.status==='waiting'?'?':item.status==='cancelled'?'–':i+1}</span><div><div class="between"><b>${esc(item.title)}</b><span class="todo-owner">${esc(item.owner)}</span></div>${item.status==='done'?'<details class="aud-todo-receipt"><summary>依据与产物</summary>':''}${item.summary?`<p>${esc(item.summary)}</p>`:''}${item.status==='done'&&item.artifact!==null&&a.version===t.version&&artifactAvailability(t)[item.artifact]?button('查看'+outputs[item.artifact],'view-artifact','quiet small',workflowBusy,`data-stage="${item.artifact}"`):''}${item.status==='done'?'</details>':''}</div></li>`).join('')}</ol>${a.reason?`<p class="muted">${esc(a.reason)}</p>`:''}</section>`;}
function handoffCard(t){const h=t.handoffs?.at(-1);if(!h||h.version!==t.version)return '';return `<section class="handoff-card"><div class="between"><b>圈人 Agent <span>→</span> 用户理解 Agent</b>${badge(h.status==='completed'?'回执已校验':h.status==='failed'?'失败已返回':h.status==='cancelled'?'已取消':'模拟委托中',h.status==='failed'?'amber':'')}</div><p>发送：人群定义、条件与资产版本、时间窗、排除规则、种子引用。</p><p>返回：${h.response?.status==='failed'?esc(h.response.reason):h.response?'SQL、模拟人群结果、执行状态与质量提示。':'等待结构化回执；用户理解 Agent 不自行修改业务目标。'}</p><details><summary>查看委托与回执</summary><div class="receipt-meta">任务 ${esc(h.taskId)} · V${h.version}<br>请求 ${esc(h.requestId)}<br>幂等标识 ${esc(h.idempotencyKey)}</div><p class="muted">版本不一致的回执拒绝采用；权限或字段缺口返回圈人 Agent 处理。</p><pre>${esc(JSON.stringify(h,null,2))}</pre></details></section>`;}
function briefCard(t){const pending=E.questions(t);return `<section class="aud-brief"><div class="between"><h3>已理解的圈选目标</h3>${badge(pending.length?'待补充':'已整理',pending.length?'amber':'green')}</div><dl>${[['任务类型',t.type],['业务意图',t.fields.action.value],['观察窗口',t.fields.window.value?'近 '+t.fields.window.value+' 天':'待明确'],['数据范围',t.fields.domain.value],['兴趣口径',t.decisions?.interest||(pending.some(q=>q.id==='interest')?'待明确':'按业务原话')],['消费口径',t.decisions?.spending||(pending.some(q=>q.id==='spending')?'待明确':'按业务原话')]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><details><summary>查看完整需求与依据</summary>${understandingTable(t)}</details></section>`;}
function conditionOverview(t){if(!t.conditions.length)return '';return `<section class="aud-condition-overview"><div class="between"><h3>本次圈选条件</h3>${badge(t.conditions.length+' 条 · V'+t.version)}</div><p class="muted">必须满足 AND · 任一满足 OR · 排除 NOT</p>${['必须满足','任一满足','排除','辅助分层','频控','黑白名单'].map(group=>{const rows=t.conditions.filter(c=>c.group===group);return rows.length?`<div class="aud-rule-group ${group==='排除'?'exclusion':''}"><h4>${esc(group)}<span>${rows.length} 条</span></h4>${rows.map(c=>`<div class="aud-rule"><b>${esc(c.name)}</b><p>${esc(c.value)}</p><small>${esc(c.domain)} · ${esc(c.assetVersion)}${c.locked?' · 规则锁定':''}</small></div>`).join('')}</div>`:'';}).join('')}</section>`;}
function previewPanel(t){const available=artifactAvailability(t),r=t.result,errors=t.conditions.length?E.validation(t):[];return `<aside class="aud-work-column aud-preview"><div class="aud-column-title"><span>RESULT PREVIEW</span><h2>人群预览</h2></div><div class="aud-column-content"><div class="aud-demo-inline">演示数据 · 尚未执行真实查询</div><section class="aud-scale"><span>${r?'本次圈选规模':'预计圈选规模'}</span><strong>${r?r.size.toLocaleString():'待执行'}${r?'<small>人</small>':''}</strong><p>${r?'模拟执行结果 · V'+r.version:'条件核验并执行后展示'}</p></section><div class="aud-preview-facts"><div><span>圈选条件</span><b>${t.conditions.length||'—'}<small>${t.conditions.length?' 条':''}</small></b></div><div><span>执行状态</span><b>${r?'已返回':workflowBusy?'处理中':t.blocker?'有缺口':'待执行'}</b></div></div><section class="aud-preview-section"><h3>条件构成</h3>${t.conditions.length?['必须满足','任一满足','排除','辅助分层','频控','黑白名单'].map(g=>{const n=t.conditions.filter(c=>c.group===g).length;return n?`<div class="aud-composition"><div><span>${g}</span><b>${n} 条</b></div><div class="aud-bar"><i style="width:${n/t.conditions.length*100}%"></i></div></div>`:'';}).join(''):'<p>策略确定后，展示入选与排除条件。</p>'}<p class="aud-preview-note">展示规则数量，不代表人群过滤比例。</p></section><section class="aud-preview-section"><h3>风险与待办</h3><div class="aud-risk-note ${errors.length?'has-risk':''}">${errors.length?esc(errors.join('；')):E.questions(t).length?'有 '+E.questions(t).length+' 项关键口径需要补充。':r?'请复核人群是否符合业务目标。真实资产覆盖与投放收益仍待验证。':'当前保留业务硬条件，资产与权限将在执行前检查。'}</div></section><section class="aud-preview-section"><div class="between"><h3>任务产物</h3><span class="muted">${available.filter(Boolean).length} / 6</span></div><nav class="artifact-menu" aria-label="任务产物">${outputs.map((name,i)=>button(`<span>${name}</span><small>${available[i]?'查看 ↗':'待生成'}</small>`,'view-artifact',artifactView===i?'selected':'',workflowBusy||!available[i],`data-stage="${i}"`)).join('')}</nav></section><details class="aud-cooperation"><summary>Agent 协作方式</summary>${roles()}</details></div></aside>`;}
function agentWorkspace(t){const list=t.activity||[],latest=list.at(-1),selected=artifactView!==null?artifactView:t.stage;const body=artifactView!==null?`<div class="between artifact-review-head"><h3>${outputs[selected]} · V${t.version}</h3>${button('回到当前任务','close-artifact','small')}</div><fieldset disabled class="artifact-readonly">${center({...t,stage:selected})}</fieldset>`:workflowBusy?`${t.conditions.length?conditionOverview(t):'<div class="aud-working-summary"><span class="activity-spinner"></span><h3>正在整理圈选方案</h3><p>左侧展示每项操作的进度，完成后在这里呈现策略和条件。</p></div>'}<div class="agent-working-hint">正在处理当前任务${button('暂停处理','pause-workflow','small')}</div>`:center(t);const centerTitle=artifactView!==null?outputs[selected]:['任务概览','明确人群定义','选择人群策略','编排圈选条件','人群结果与评估','保存策略档案'][t.stage];return `<div class="aud-workbench"><aside class="aud-work-column aud-conversation"><div class="aud-column-title"><span>AGENT CONVERSATION</span><h2>需求与执行过程</h2></div><div class="aud-column-content"><div class="aud-agent-intro"><span class="agent-avatar">圈</span><p>我会保留业务约束，逐项展示圈选依据和执行结果。</p></div><div class="user-message"><span>你</span><p>${esc(t.query)}</p></div>${latest?activityCard(t,latest):'<p class="muted">已载入历史任务，后续操作会记录在这里。</p>'}${briefCard(t)}${latest?.status==='cancelled'&&!workflowBusy?`<div class="warnbox">处理已暂停。${button('继续处理','resume-workflow','small')}</div>`:''}${list.length>1?`<details class="activity-history"><summary>此前处理记录 · ${list.length-1} 次</summary>${list.slice(0,-1).map(a=>activityCard(t,a)).join('')}</details>`:''}${t.handoffs?.length?`<details class="aud-cooperation"><summary>用户理解 Agent · ${t.handoffs.at(-1).status==='completed'?'已返回执行结果':'协作记录'}</summary>${handoffCard(t)}</details>`:''}<details class="aud-cooperation"><summary>业务原话与参考资料</summary>${left(t)}</details></div></aside><main class="aud-work-column aud-canvas"><div class="aud-column-title between"><div><span>AUDIENCE WORKSPACE</span><h2>${centerTitle}</h2></div>${badge('V'+t.version)}</div><div class="aud-column-content aud-canvas-body">${body}</div></main>${previewPanel(t)}</div>`;}

const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function operate(t,title,items){
 if(workflowBusy)throw Error('当前任务仍在处理');workflowBusy=true;artifactView=null;
 const a=E.beginActivity(t,title,items);persist();render();
 try{for(let i=0;i<items.length;i++){
  if(current()?.id!==t.id||a.version!==t.version||a.status==='cancelled')return false;
  E.updateActivity(t,a.id,i,'running');persist();render();await pause(420);
  if(current()?.id!==t.id||a.version!==t.version||a.status==='cancelled')return false;
  try{const result=await items[i].work();const status=result?.status||'done';E.updateActivity(t,a.id,i,status,result?.summary||String(result||''));persist();render();if(status!=='done')return false;}
  catch(err){for(const h of t.handoffs||[])if(h.version===t.version&&['prepared','running'].includes(h.status)){h.status='failed';h.response={status:'failed',reason:err.message,taskId:t.id,version:t.version,requestId:h.requestId};}E.updateActivity(t,a.id,i,'blocked',err.message);E.log(t,'操作受阻：'+err.message);persist();return false;}
 }return true;}finally{workflowBusy=false;persist();render();}
}
async function understandFlow(t){return operate(t,'圈人 Agent 正在整理方案',[
 {title:'识别任务类型',artifact:0,work:()=>{t.stage=1;return '识别为'+t.type+'；保留业务原话与任务标识';}},
 {title:'提取业务上下文',artifact:1,work:()=> '已整理业务对象、时间窗、数据范围与排除约束；'+E.questions(t).length+' 项关键口径待补充'},
 {title:'检索历史策略',work:()=>{const refs=tasks.filter(x=>x.id!==t.id&&x.archived&&!x.invalid&&x.scenario===t.scenario);t.historyMatches=refs.map(x=>({id:x.id,version:x.version,title:x.title}));return refs.length?'找到 '+refs.length+' 份同场景本地策略，仅作为本次参考':'没有可直接复用的本地档案；按本次需求生成，不假定历史效果';}},
 {title:'核对关键口径',work:()=>{const pending=E.questions(t);if(!['直接圈人','复用历史策略','分析转圈人'].includes(t.type))return {status:'blocked',summary:'此请求需先转译为明确的人群定义'};return pending.length?{status:'waiting',summary:'只有 '+pending.length+' 项会改变入选范围，需要业务补充；其他已明确信息直接采用'}:'关键口径完整，无需重复确认';}},
 {title:'生成候选人群策略',artifact:2,work:()=>{E.confirm(t);picked=new Set(['balanced']);return '按已确认约束形成保守、平衡、探索三种演示方案；差异、排除和风险已写入策略卡，等待选择';}}
 ]);}
async function executeFlow(t,map=false){let req=null;const entries=[];
 if(map)entries.push({title:'映射可执行资产',artifact:3,work:()=>{E.select(t,[...picked]);return '已将策略映射为 '+t.conditions.length+' 条条件，保留 AND / OR / 排除关系与资产版本';}});
 entries.push({title:'检查条件、权限与数据范围',owner:'圈人 Agent · 规则校验',artifact:3,work:()=>{const errors=E.validation(t);if(errors.length){t.stage=3;throw Error(errors.join('、'));}t.conditionConfirmed=true;t.stage=4;return '模拟检查通过，核心条件未放宽；可以委托执行';}},
 {title:'组织执行委托',work:()=>{req=E.prepareHandoff(t);req.status='running';return '发送任务 ID、V'+t.version+'、条件单和风险约束；使用请求标识关联后续回执';}},
 {title:'生成查询方案与 SQL',owner:'用户理解 Agent（模拟）',work:()=>{req.generatedSql=E.sql(t);return '根据收到的条件生成示例 SQL；不调整用户目标或排除条件';}},
 {title:'核验 SQL 与委托版本',owner:'圈人 Agent · 规则校验',work:()=>{if(req.version!==t.version||!E.executable(t))throw Error('委托版本或执行条件发生变化，停止执行');return '委托与当前任务版本一致；查询绑定确认条件，真实 SQL 校验服务尚待接入';}},
 {title:'运行查询并回读结果',owner:'用户理解 Agent / 执行服务（模拟）',work:()=>{const run=E.run(t,runFailure||null);if(run.status==='失败'){E.acceptHandoff(t,{requestId:req.requestId,taskId:t.id,version:t.version,status:'failed',reason:run.reason});throw Error(run.reason+'；已返回圈人 Agent，未修改业务条件');}return '模拟运行完成，返回运行编号与人群结果；尚未执行真实数据查询';}},
 {title:'核对回执并解释人群',artifact:4,work:()=>{E.acceptHandoff(t,{requestId:req.requestId,taskId:t.id,version:t.version,resultVersion:t.result.version,status:'completed',sql:t.result.sql,runId:t.result.runId,audienceSize:t.result.size,quality:'模拟结果；覆盖需核实、收益待验证'});return '已校验任务与版本，输出人群解释、SQL、运行日志及评估报告，等待业务复核';}});
 return operate(t,map?'圈人 Agent 正在构建并执行方案':'圈人 Agent 正在协调执行',entries);
}
async function archiveFlow(t){return operate(t,'圈人 Agent 正在沉淀本次方案',[
 {title:'核对结果与业务复核',work:()=>{if(!t.result?.approved||t.result.version!==t.version)throw Error('当前版本尚未通过业务复核');return '当前结果已复核；采纳反馈与收益验证分别记录';}},
 {title:'绑定产物与版本',work:()=> '需求、策略、条件、执行回执、评估与过程记录绑定 V'+t.version},
 {title:'保存可复用策略档案',artifact:5,work:()=>{t.archived=true;t.invalid=false;E.log(t,'保存策略档案及 Agent 操作摘要');return '已保存到当前浏览器；实际业务使用与效果证据仍待回收';}}
 ]);}

const sceneCopy={brand:['新品推广','找到对新品有兴趣的消费者','bag'],acquisition:['品牌拉新','从品类买家中发现品牌新客','plus'],recall:['老客召回','找回一段时间没有购买的用户','return'],repurchase:['复购提醒','找到进入补货周期的老客','cycle'],local:['门店获客','发现周边有相关兴趣的用户','pin'],cross:['跨域找人','发掘其他业务域的消费潜力','cross']};
function icon(name){const paths={spark:'M12 3l2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4Z',bag:'M5 7h14l1 13H4L5 7ZM8 8V6a4 4 0 0 1 8 0v2',plus:'M12 5v14M5 12h14',return:'M7 7h7a6 6 0 0 1 0 12H8M7 3 3 7l4 4',cycle:'M19 8a8 8 0 0 0-13-2L3 9m0-5v5h5M5 16a8 8 0 0 0 13 2l3-3m0 5v-5h-5',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0ZM14 10a2 2 0 1 1-4 0 2 2 0 1 1 4 0',cross:'M3 7h14m-4-4 4 4-4 4M21 17H7m4-4-4 4 4 4',attach:'m9 13 6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l8-8',arrow:'M5 12h14m-6-6 6 6-6 6',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 1 1 18 0'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.spark).split('|').map(d=>`<path d="${d}"/>`).join('')}</svg>`;}
function home(){return `<main class="aud-landing"><div class="aud-welcome"><span class="aud-welcome-mark">${icon('spark')}</span><h2>这次，想找到哪些人？</h2><p>说出业务目标，帮你整理人群策略，找到合适的资产。</p></div><div class="aud-prompt-box">${seedAsset?`<div class="aud-seed-chip">已带入资产 · ${esc(seedAsset.name)}${button('移除','clear-seed','quiet small')}</div>`:''}<label class="aud-sr-only" for="aud-query">描述圈人需求</label><textarea id="aud-query" aria-label="描述圈人需求" placeholder="例如，为羽绒服新品找到近90天买过服饰、有相关兴趣的中高消费用户……">${esc(draftQuery)}</textarea>${upload.length?`<div class="aud-attachment-chips">${upload.map(x=>`<span>${icon('attach')}${esc(x.name)}</span>`).join('')}</div>`:''}<div class="aud-prompt-tools"><div class="aud-input-options"><label class="aud-attach-button" tabindex="0" role="button" aria-label="添加参考材料">${icon('attach')}<span>参考材料</span><input type="file" id="aud-material" accept=".md,.txt,.pdf,.png,.jpg,.jpeg" multiple></label><details class="aud-options"><summary>更多设置 <span>⌄</span></summary><div class="aud-options-popover"><label for="aud-scope">数据范围</label><select id="aud-scope" aria-label="任务数据范围"><option value="portal" ${scope==='portal'?'selected':''}>按需求匹配业务域</option><option value="ldmp" ${scope==='ldmp'?'selected':''}>仅生服 LDMP</option></select><label for="create-platform">使用平台 · 选填</label><input id="create-platform" aria-label="使用平台" value="${esc(draftPlatform)}" placeholder="可在交付前补充"><p>文本材料可读取；PDF 与图片目前仅记录文件名。</p></div></details></div>${button('开始圈人 '+icon('arrow'),'create','aud-start-button',!draftQuery.trim())}</div></div><div class="aud-input-caption"><span>只在关键口径不明确时向你提问</span><span>⌘ / Ctrl + Enter 发送</span></div><section class="aud-suggestions"><div class="aud-section-caption">也可以从这些场景开始</div><div class="aud-suggestion-grid">${E.featured.map(k=>{const [name,desc,mark]=sceneCopy[k];return `<button class="aud-suggestion" data-action="scene" data-key="${k}" aria-label="${name}示例"><span class="aud-suggestion-icon">${icon(mark)}</span><span><b>${name}</b><small>${desc}</small></span><span class="aud-suggestion-arrow">↗</span></button>`;}).join('')}</div></section>${tasks.length?`<section class="aud-recent"><div class="between"><h3>最近任务</h3>${button('查看全部','archives','quiet small')}</div>${tasks.slice().reverse().slice(0,3).map(t=>`<button class="aud-recent-row" data-action="resume" data-id="${t.id}"><span class="aud-recent-icon">${icon('clock')}</span><span class="aud-recent-name"><b>${esc(t.query||t.title)}</b><small>${esc(t.created.slice(0,10))} · ${esc(t.title)}</small></span><span class="aud-recent-state">${esc(state(t))}</span><span>›</span></button>`).join('')}</section>`:''}<p class="aud-home-footnote">演示环境 · 策略与结果为模拟数据</p></main>`;}

function taskCard(t){return `<div class="archive-card" style="margin-bottom:10px"><div class="between"><div><span class="muted">${esc(t.id)} · v${t.version}</span><h3>${esc(t.title)}</h3></div>${badge(state(t),t.blocker?'amber':t.result?.approved?'green':'')}</div><p class="muted">${esc(t.query)}</p><div class="actions">${button('继续任务','resume','small',false,`data-id="${t.id}"`)}${button('复用为新任务','reuse','small',false,`data-id="${t.id}"`)}</div></div>`;}
const stageNotes=[
 ['任务创建','输入业务原话或带入门户资产，建立圈人任务。','一份保留原话与来源的任务'],
 ['我们已整理需求，只补关键问题','原话中明确的信息直接采用。只处理会改变入选范围的歧义与缺失。','需求理解单'],
 ['决定圈谁，以及为什么','比较保守、平衡和探索方案，确认取舍与排除范围。','人群策略卡'],
 ['系统核对资产与执行条件','口径映射、权限和版本由系统检查；只有缺口或条件变化需要你处理。','执行条件单'],
 ['执行后，再判断结果能不能用','根据确认版本运行，检查质量、记录业务反馈；有偏差可退回修改。','人群包与评估报告'],
 ['留下可复用、可追溯的方案','保存版本、采纳反馈与计划去向，为后续真实使用和效果回收留好关联。','策略档案']
];
function progress(t){const currentStep=t?t.stage:0;const completed=t?[true,t.confirmed,t.strategyConfirmed,t.conditionConfirmed,!!t.result?.approved,t.archived]:[];return `<nav class="steps" aria-label="圈人六步流程">${titles.map((name,i)=>{const enabled=!!t&&(i<=t.stage||completed[i]);return `<button type="button" data-action="step" data-step="${i}" ${enabled?'':'disabled'} ${i===currentStep?'aria-current="step"':''} class="${i===currentStep?'current':completed[i]?'done':''}"><span class="step-num">${completed[i]&&i!==currentStep?'✓':String(i+1).padStart(2,'0')}</span><span><b>${name}</b><small>${i===currentStep?'当前步骤':completed[i]?'已完成 · 可回看':outputs[i]}</small></span></button>`;}).join('')}</nav>`;}
function workspace(t){return agentWorkspace(t);}
function left(t){return `<span class="label">业务原话</span><div class="bubble">${esc(t.query)}</div><span class="label">任务识别</span>${badge(t.type)}<div class="chatnote">${t.stage===0?'任务已建立。原话与参考材料已保留，下一步整理需求。':t.stage===1?'明确的原话直接采用；页面只追问影响入选范围的关键问题。':t.stage===2?'比较候选策略，先确认“圈谁、为什么”，再匹配资产。':t.stage===3?'每个核心条件都要有口径与权限依据。存在缺口时停止执行。':t.stage===4?'按当前已确认版本演示执行。真实 SQL Agent 接口尚未接入。':'保留版本与使用记录。业务采纳不等于策略已验证有效。'}</div>${t.attachedAssets.length?`<div class="attachment-context">门户带入 ${esc(t.attachedAssets.map(a=>a.name).join('、'))}<br>仅作需求参考，不自动获得权限。</div>`:''}<span class="label">材料来源</span><p class="muted">${esc(E.scenarios[t.scenario].source)}<br>场景为业务抽象示例，资产与自动校验为演示构造。</p>${t.materials.map(m=>`<div class="material">▧ ${esc(m.name)} · ${esc(m.note)}${m.text?`<details><summary>查看材料摘录</summary>${esc(m.text.slice(0,500))}</details>`:''}</div>`).join('')}<label class="filelabel">＋ 添加参考材料<input type="file" id="aud-material" accept=".md,.txt,.pdf,.png,.jpg,.jpeg" multiple></label><details><summary>补充说明与修改记录</summary><textarea id="aud-note" aria-label="补充说明" placeholder="记录补充依据；影响人群定义的内容请同时修改对应字段"></textarea>${button('记录说明','note','small')}<div>${t.notes.map(n=>`<p class="muted">${esc(n)}</p>`).join('')}</div></details>${button('修改需求 · 新版本','revise-need','small',!t.confirmed)}<details><summary>任务过程记录（${t.history.length}）</summary>${t.history.slice().reverse().map(x=>`<div class="runline"><span class="muted">v${x.version} · ${esc(x.at.slice(11,19))}</span><br>${esc(x.action)}</div>`).join('')}</details>`;}
function center(t){if(t.stage===0)return creation(t);if(t.stage===1)return understanding(t);if(t.stage===2)return strategies(t);if(t.stage===3)return conditions(t);if(t.stage===4)return execution(t);return archiveDetail(t);}
function creation(t){return section('任务卡已生成','业务原话、来源和后续产物绑定同一任务',`<div class="successbox">已识别为${esc(t.type)}任务。已明确的信息直接继承，下一步仅处理关键口径。</div><label class="label">业务原话</label><div class="bubble">${esc(t.query)}</div><div class="facts artifact-grid">${[['任务 ID',t.id],['业务场景',t.title],['使用平台',t.fields.platform.value],['资料来源',t.materials.length+' 份参考材料'+(t.attachedAssets.length?' · 门户资产带入':' · 业务输入')]].map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="action-footer"><span class="muted">任务已保存到当前浏览器</span>${button('进入需求理解 →','step','primary',false,'data-step="1"')}</div>`,badge('已创建','green'));}
function understandingTable(t){const pending=E.questions(t);const rows=[['目标需求',t.query,'原话提取','保留业务表达，不自行扩大目标'],['目标行为',t.fields.action.value,'场景理解',t.fields.action.source],['观察时间',t.fields.window.value?'近 '+t.fields.window.value+' 天':'待补充',t.fields.window.value?'原话 / 补充':'待补充',t.fields.window.source],['数据范围',t.fields.domain.value,'上下文提取',t.fields.domain.source],['兴趣定义',t.decisions?.interest||(/搜索|收藏|加购|互动/.test(t.query)?'按原话中的明确行为条件':pending.some(x=>x.id==='interest')?'待补充':'按原话；无额外兴趣限制'),pending.some(x=>x.id==='interest')?'待补充':'已明确','对应兴趣行为资产'],['消费口径',t.decisions?.spending||(pending.some(x=>x.id==='spending')?'待补充':'按原话；不额外提高门槛'),pending.some(x=>x.id==='spending')?'待补充':'已明确','真实分层以供应方定义为准'],['排除条件',t.fields.exclude.value,'业务约束','用户定义 + 平台治理约束'],['交付与验收',t.fields.success.value,'当前交付','不预填业务收益']];return section('结构化需求理解','自动整理，展示来源；明确的信息不再逐项确认',`<div class="table-scroll"><table class="understanding-table"><thead><tr><th>字段</th><th>结构化结果</th><th>状态</th><th>依据 / 处理</th></tr></thead><tbody>${rows.map(([k,v,status,why])=>`<tr><th>${k}</th><td>${esc(v)}</td><td>${badge(status,status==='待补充'?'amber':status==='已明确'||status==='原话提取'?'green':'')}</td><td class="muted">${esc(why||'业务输入')}</td></tr>`).join('')}</tbody></table></div>`);}

function understanding(t){
 if(!['直接圈人','复用历史策略','分析转圈人'].includes(t.type))return `<div class="warnbox"><b>识别为${esc(t.type)}请求</b><p>当前不能直接圈人。${t.type==='分析'?'先提供已有分析结论，再转成人群定义。':'需要对应业务或数据负责人处理。原始需求已保留。'}</p></div>${t.type==='分析'?`<textarea id="analysis-conclusion" aria-label="已有分析结论" placeholder="已有结论与希望圈选的人群"></textarea>${button('基于已有结论继续','analysis-convert','primary')}`:''}<div class="actions">${button('复制需求摘要','copy-route')}${button('返回创建','home')}</div>`;
 const pending=E.questions(t),answers=Object.entries(t.decisions||{});
 return `<details class="understanding-artifact"><summary>查看需求理解单 · 字段、来源与口径</summary>${understandingTable(t)}</details>${answers.length?`<details><summary>已补充的关键口径 · ${answers.length} 项</summary>${answers.map(([id,v])=>`<div class="summary-item"><p>${esc(v)}</p>${button('重新选择','reopen-decision','quiet small',t.confirmed,`data-id="${id}"`)}</div>`).join('')}</details>`:''}${t.confirmed?'<div class="successbox">当前理解已进入方案。需要调整时可修改需求并生成新版本。</div>':`<div class="section-head between"><h3>${pending.length?'只需要你补充 '+pending.length+' 个关键问题':'关键口径已清楚，可以继续'}</h3>${badge(pending.length?'影响人群范围':'无需逐项确认',pending.length?'amber':'green')}</div>${pending.length?pending.slice(0,3).map((q,i)=>`<div class="decision-card"><div class="decision-number">${i+1}</div><h3>${esc(q.title)}</h3><p>${esc(q.why)}</p><div class="decision-choices">${q.choices.map((v,n)=>button(esc(q.id==='window'?v+'天':v),'answer-choice','',false,`data-id="${q.id}" data-choice="${n}"`)).join('')}</div><details ${q.choices.length?'':'open'}><summary>填写业务已有口径</summary><input id="answer-${q.id}" aria-label="${esc(q.title)}" placeholder="填写具体规则或补充信息">${button('采用此口径','answer-custom','small',false,`data-id="${q.id}"`)}</details></div>`).join(''):'<p class="muted">明确条件不再重复提问。生成方案后仍可修改，资产存在性与权限将在执行前核验。</p>'}${pending.length>3?'<p class="muted">先完成以上关键问题，下一组问题随后展示。</p>':''}`}
 <details><summary>修改原始需求 / 查看其他信息</summary><textarea id="edit-query" aria-label="修改原始需求">${esc(t.query)}</textarea>${button('更新需求并重新理解','update-query','small')}<dl class="context-list">${['action','platform','exclude','success'].map(k=>`<dt>${labels[k]}</dt><dd>${esc(t.fields[k].value)}<span class="muted"> · ${esc(t.fields[k].source||t.fields[k].status)}</span></dd>`).join('')}</dl></details><div class="actions">${button('生成策略 →','confirm-need','primary',t.confirmed||pending.length>0)}</div>`;
}
const strategySpecs=[['conservative','保守策略','优先明确且较强的行为证据','信息较少但实际有潜力的用户可能被遗漏'],['balanced','平衡策略','保留核心条件，使用中强行为与已有偏好','部分历史偏好可能不代表当前需求'],['explore','探索策略','允许待验证的弱信号作为增强依据','辅助分层仍需验证，不代表当前购买意向']];
function strategies(t){const prior=tasks.filter(x=>x.id!==t.id&&x.archived&&!x.invalid&&x.scenario===t.scenario);return `<details class="aud-shared-rules"><summary>共同条件 · 近 ${esc(t.fields.window.value)} 天 · ${esc(t.fields.domain.value)}</summary><p>${esc(t.query)}</p><div class="aud-rule-chips"><span>近 ${esc(t.fields.window.value)} 天</span><span>${esc(t.fields.domain.value)}</span><span>保留业务排除与治理规则</span></div></details><div class="section-head"><h3>选择本次人群策略</h3><p class="muted">建议从平衡策略开始；也可以组合方案。</p></div><div class="strategy-grid aud-readable-strategies">${[strategySpecs[1],strategySpecs[0],strategySpecs[2]].map(([id,name,reason,risk])=>`<article class="strategy ${picked.has(id)?'selected':''}"><label><input type="checkbox" data-pick="${id}" ${picked.has(id)?'checked':''} ${t.strategyConfirmed?'disabled':''}><b>${name}</b>${id==='balanced'?badge('建议起点'):''}</label><h4>${id==='conservative'?'更严格地筛选明确兴趣':id==='balanced'?'按已确认的业务条件圈选':'保留条件，增加探索分层'}</h4><p>${id==='conservative'?'在共同条件上，额外要求核心行为出现多次。适合优先关注明确意向的任务。':id==='balanced'?'沿用已确定的兴趣与消费口径，不额外提高入选门槛。': '在符合全部硬条件的人群内，用辅助偏好标记分层，供后续分别验证。'}</p><div class="aud-strategy-risk"><b>需要权衡</b><span>${esc(risk)}</span></div></article>`).join('')}</div><p class="aud-evidence-note">依据来自业务原话与已补充口径；方案差异为演示设计，效果尚待验证。</p><details><summary>历史策略参考 · ${prior.length} 份</summary><p>${t.reusedFrom?'本次复用了历史任务，资产与权限仍需重新检查。':prior.length?'已找到同场景本地档案，可在资产沉淀中比较。':'暂无同场景已归档策略，本次按业务需求生成。'}</p></details><details><summary>补充选择理由或调整说明</summary><textarea id="strategy-note" aria-label="策略调整说明" ${t.strategyConfirmed?'disabled':''}>${esc(t.strategy?.note||'')}</textarea></details><details><summary>模拟协作异常（评审用）</summary><select id="strategy-failure" aria-label="模拟协作异常"><option value="">正常完成</option><option value="permission">资产权限不足，委托前阻断</option><option value="sql">执行失败，由圈人 Agent 接回处理</option></select></details><div class="action-footer">${button('返回需求理解','revise-need')}${button(t.strategyConfirmed?'修改策略 · 新版本':picked.size>1?'采用合并策略并试跑 →':'采用此策略并试跑 →',t.strategyConfirmed?'revise-strategy':'confirm-strategy','primary',!picked.size)}</div>`;}

function riskChecks(t){const errors=E.validation(t);return [['逻辑与取值',errors.some(x=>/条件|需求|方案/.test(x))?'需处理':'模拟通过'],['资产与口径',['missing','definition'].includes(t.blocker)?'已阻断':'模拟通过'],['权限',t.blocker==='permission'||t.conditions.some(x=>x.permission!=='演示可用')?'已阻断':'模拟通过'],['资产时效',t.blocker==='stale'?'已阻断':'模拟通过'],['跨域映射',t.blocker==='mapping'?'已阻断':t.fields.domain.value==='跨域'?'模拟通过':'不涉及'],['样本与覆盖','执行后评估']];}

function conditions(t){const errors=E.validation(t);return `${errors.length?`<div class="errorbox"><b>核心条件存在缺口 · 暂停执行</b><p>${esc(errors.join('、'))}。保留当前条件，处理完成后重新校验。</p></div>`:''}${section('条件逻辑编排','必须满足 AND（任一满足 OR）AND NOT 排除；平台治理约束始终保留',`<div class="condition-list">${t.conditions.map((c,i)=>`<div class="condition-row ${t.blocker==='permission'&&i===0?'blocked':''}"><div class="logic-token">${c.group==='排除'||c.group==='黑白名单'?'NOT':c.group==='任一满足'?'OR':'AND'}</div><div class="condition-main"><div class="row">${badge(c.group)}<strong>${esc(c.name)}</strong></div><p>${esc(c.value)}</p><div class="asset-meta">${esc(c.domain)} · ${esc(c.owner)} · ${esc(c.assetVersion)} · 更新 ${esc(c.updated)}</div><details><summary>资产依据${!t.conditionConfirmed&&!c.locked?'与条件修改':''}</summary><p class="muted">${esc(c.id)} · ${esc(c.definition)}</p><div class="form-grid"><select aria-label="${esc(c.name)}逻辑组" data-condition-group="${i}" ${t.conditionConfirmed||c.locked?'disabled':''}>${(c.group==='辅助分层'?['辅助分层']:['必须满足','任一满足','排除','频控','黑白名单']).map(g=>`<option ${g===c.group?'selected':''}>${g}</option>`).join('')}</select><input aria-label="${esc(c.name)}取值" data-condition-value="${i}" value="${esc(c.value)}" ${t.conditionConfirmed||c.locked?'disabled':''}></div></details></div><div class="condition-status">${badge(t.blocker==='permission'&&i===0?'模拟待授权':c.permission,t.blocker==='permission'&&i===0?'red':'green')}<p>${c.locked?'规则已锁定':c.core?'核心条件':'辅助分层'}</p></div></div>`).join('')}</div>`,badge('策略 V'+t.version))}${section('执行前检查','系统检查已构建条件，用户只处理缺口或业务取舍',`<div class="risk-grid">${riskChecks(t).map(([name,status])=>`<div class="risk-check ${status==='已阻断'||status==='需处理'?'error':status==='执行后评估'?'pending':''}"><b>${status==='已阻断'||status==='需处理'?'!':status==='执行后评估'?'○':'✓'} ${name}</b><span>${status}</span></div>`).join('')}</div>${t.blocker?`<div class="warnbox">${t.blocker==='permission'?'需资产 Owner 授权；门户入口可查看申请流程。':'需业务或供应方补齐依据，不会静默替换核心条件。'}<div class="actions">${button('查看门户申请入口','portal','small')}${button('模拟问题已解决','resolve','small')}</div></div>`:''}<details><summary>补充种子样本（可选）</summary><input id="seed-ref" aria-label="种子用户引用" placeholder="DEMO-SEED-01；仅填写演示标识" value="${esc(t.seedRef||'')}" ${t.conditionConfirmed?'disabled':''}></details><details><summary>演示异常分支</summary><select id="aud-blocker" aria-label="演示阻断类型"><option value="">全部演示检查通过</option>${Object.entries(E.blockers).filter(([k])=>!['sql','sample'].includes(k)).map(([k,v])=>`<option value="${k}" ${t.blocker===k?'selected':''}>${v}</option>`).join('')}</select></details><div class="action-footer">${button('修改策略','revise-strategy')}<div class="row">${t.conditionConfirmed?button('修改条件 · 新版本','revise-condition'):''}${button('确认条件，进入执行评估 →','check-and-execute','primary',errors.length>0)}</div></div>`)}<details><summary>查看结构化执行条件</summary><pre>${esc(JSON.stringify({task:t.id,version:t.version,conditions:t.conditions},null,2))}</pre></details>`;}

function execution(t){const r=t.result,last=t.runs.at(-1);const summary=r?`<div class="execution-summary">${[['运行状态','模拟执行完成'],['运行版本','V'+r.version],['人群规模',r.size.toLocaleString()+'（示例）'],['数据分区',r.partition]].map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div>`:`<div class="info-strip"><b>${running?'正在模拟执行…':'执行条件已就绪'}</b><span>按当前版本生成示例 SQL，回读人群与评估结果。</span></div>`;let panel='';if(executionTab==='sql')panel=`<div class="between"><span class="muted">${r?'模拟完成；未执行真实数据查询':'示例 SQL 预览 · 尚未执行'}</span>${badge('V'+t.version)}</div><pre class="sql-code">${esc(r?.sql||E.sql(t))}</pre>${r?`<div class="actions">${button('复制示例 SQL','copy-sql','small')}</div>`:''}`;if(executionTab==='logs')panel=`<div class="step-line">✓ 当前方案与执行条件版本一致</div><div class="step-line">✓ 演示条件通过检查，真实授权待接口接入</div>${t.runs.length?runs(t):'<div class="empty">尚未发起执行</div>'}`;if(executionTab==='audience')panel=r?`<h3>这批人为什么被圈入？</h3><p class="explanation">${esc(t.fields.definition.value)}</p><div class="info-strip">排除规则：${esc(t.fields.exclude.value)}</div><div class="sample-grid">${r.sampleIds.map(x=>`<div>${esc(x)}<span>演示标识 · 非真实用户</span></div>`).join('')}</div><p class="muted">仅提供 3 条演示样例。真实人群需在获准环境中交付。</p>`:'<div class="empty">执行后展示人群解释与演示样例</div>';if(executionTab==='quality')panel=r?`<div class="quality-list"><div><b>条件一致性</b><span>当前 V${r.version} 的规则已绑定运行记录</span>${badge('模拟通过','green')}</div><div><b>资产覆盖</b><span>部分偏好资产覆盖不足，真实执行时需核实</span>${badge('待核实','amber')}</div><div><b>种子样本</b><span>${t.seedRef?'已关联 '+esc(t.seedRef)+'；命中情况为演示':'未提供，不生成种子命中结论'}</span>${badge(t.seedRef?'已关联':'未评估')}</div><div><b>业务收益</b><span>需要消费方实验回传，人群规模不代表增量收益</span>${badge('待验证')}</div></div>`:'<div class="empty">执行后生成质量评估，不提前展示评分</div>';return `${r?`<details class="aud-result-conditions"><summary>查看入选与排除条件 · ${t.conditions.length} 条</summary>${conditionOverview(t)}</details>`:''}${summary}${last?.status==='失败'&&!r?`<div class="errorbox">${esc(last.reason)} · 连续失败 ${t.attempts}/3。${t.attempts>=3?'已停止自动尝试，请转人工处理。':'检查条件后可重试。'}</div>`:''}${section('执行与评估','SQL、运行记录、人群说明和质量判断绑定同一版本',`<div class="execution-tabs" role="tablist">${[['sql','SQL'],['logs','运行日志'],['audience','人群解释'],['quality','质量评估']].map(([id,label])=>`<button role="tab" aria-selected="${executionTab===id}" data-action="execution-tab" data-tab="${id}" class="${executionTab===id?'active':''}">${label}</button>`).join('')}</div><div role="tabpanel" class="execution-pane">${panel}</div>`)}${r?`${section('业务复核','仅记录是否符合需求，效果验证在业务实验后回收',`<textarea id="review-feedback" aria-label="业务抽检反馈" placeholder="可记录偏差、抽检结论或修改建议">${esc(t.feedback)}</textarea><div class="action-footer"><div class="row">${button('退回修改策略','revise-strategy')}${button('退回修改条件','revise-condition')}</div><div class="row">${button('评估报告','report')}${button('导出演示包','export-csv')}${r.approved?button('查看资产沉淀 →','step','primary',false,'data-step="5"'):button('通过，进入资产沉淀 →','approve','primary')}</div></div>`)}`:`<details><summary>执行异常演示</summary><select id="run-failure" aria-label="模拟执行结果"><option value="">模拟成功</option><option value="sql" ${runFailure==='sql'?'selected':''}>SQL 执行失败</option><option value="sample" ${runFailure==='sample'?'selected':''}>结果样本量过小</option></select></details><div class="action-footer">${button('返回条件','back-condition','',running)}${button(t.attempts>=3?'下载人工处理记录':running?'正在执行…':t.attempts?'重试模拟执行':'运行演示',t.attempts>=3?'report':'run','primary',running||(!E.executable(t)&&t.attempts<3))}</div>`}`;}

function runs(t){return t.runs.map(r=>`<div class="runline">${esc(r.id)} · v${r.version} · ${esc(r.status)} ${r.reason?' / '+esc(r.reason):''}<br><span class="muted">${esc(r.at)}</span></div>`).join('');}
function right(t){const done=[true,t.confirmed,t.strategyConfirmed,t.conditions.length>0,!!t.result,t.archived];const pending=t.stage===1?E.questions(t).length:0;return `<div class="artifact-current"><span>当前产物</span><h3>${outputs[t.stage]}</h3><b>V${t.version} · ${done[t.stage]?'已生成':'待完成'}</b><p>关联当前任务与策略版本</p></div><div class="side-section"><h3>通过条件</h3><p>${t.stage===0?'✓ 业务原话已保留':t.stage===1?pending?'○ '+pending+' 个关键口径待补充':'✓ 关键口径已明确':t.stage===2?t.strategyConfirmed?'✓ 业务策略已确定':'○ 选择本次人群策略':t.stage===3?E.validation(t).length?'○ 处理执行前缺口':'✓ 模拟条件检查通过':t.stage===4?t.result?.approved?'✓ 结果已复核':t.result?'○ 业务复核结果':'○ 执行并回读结果':t.archived?'✓ 策略档案已保存':'○ 保存方案与使用记录'}</p><p>✓ 上游依据保留</p></div><div class="side-section"><h3>风险 / 待处理</h3><p class="${t.blocker?'pending':'muted'}">${t.blocker?esc(E.blockers[t.blocker]):t.stage<4?'真实资产与授权待接入；当前使用模拟状态':'业务效果待回传，尚不能证明收益'}</p></div><div class="side-section"><h3>关联产物</h3>${outputs.map((n,i)=>`<div class="artifact-link"><span>${n}</span><span class="${done[i]?'complete':'muted'}">${done[i]?'✓':'—'}</span></div>`).join('')}</div><details><summary>过程记录 · ${t.history.length}</summary>${t.history.slice(-5).reverse().map(x=>`<p class="muted">V${x.version} · ${esc(x.action)}</p>`).join('')}</details>${button('保存草稿','save','quiet small')}`;}

function compare(t,v){const old=t.versions.find(x=>x.version===v);if(!old)return '';return `<div class="compare">${[[v,old],[t.version,t]].map(([version,item])=>`<div><b>V${version} · ${version===t.version?'当前':'历史'}</b><p>${esc(item.query||item.fields.object.value)}</p><p class="muted">策略 ${esc(item.strategy?.ids.join(' / ')||'未确认')}</p>${item.conditions.map(c=>`<p><b>${esc(c.group)} · ${esc(c.name)}</b>${esc(c.value)}</p>`).join('')}<p>${item.result?'模拟结果 '+item.result.size.toLocaleString()+' 人':'暂无结果'}</p></div>`).join('')}</div>`;}
function archiveDetail(t){const peers=tasks.filter(x=>x.id!==t.id&&x.archived&&!x.invalid&&x.scenario===t.scenario);return section('策略档案','全链路产物、版本与使用反馈一起保留',`<div class="archive-banner"><span>方案名称</span><h2>${esc(t.title)}</h2><p>${esc(t.id)} · V${t.version} · ${esc(t.fields.domain.value)}</p></div><div class="linked-artifacts">${['需求理解单','人群策略卡','执行条件单','示例 SQL','演示人群包','业务复核记录'].map(n=>`<div><b>✓ ${n}</b><span>已绑定当前 V${t.version}</span></div>`).join('')}<div><b>○ 效果证据</b><span>待消费方实验回传</span></div></div><div class="form-grid"><div><label class="label">方案名称</label><input id="archive-title" aria-label="方案名称" value="${esc(t.title)}"></div><div><label class="label">业务使用反馈</label><select id="adoption" aria-label="业务采纳状态">${['未采纳','计划使用','已采纳（用户反馈）','不采纳'].map(x=>`<option ${x===t.adoption?'selected':''}>${x}</option>`).join('')}</select></div></div><label class="label">计划使用去向 / 负责人（选填）</label><input id="destination" aria-label="使用去向" value="${esc(t.destination)}" placeholder="记录使用计划，不会实际下发"><div class="action-footer"><span class="muted">业务采纳与效果验证分别记录</span><div class="row">${button('下载策略档案','report')}${button('保存策略档案','archive','primary')}</div></div>`,badge(t.invalid?'已标记失效':t.archived?'已保存':'待沉淀',t.invalid?'amber':'green'))+section('相似需求优先参考','仅展示当前浏览器中真实保存过的同场景档案，不编造历史收益',peers.length?peers.slice(0,2).map(taskCard).join(''):'<p class="muted">暂无其他同场景档案。本次保存后，可从“策略档案”复用并重新校验。</p>')+section('版本管理','需求、策略或条件发生变化时创建新版本；恢复后重新校验',`<div class="version-current">${badge('V'+t.version+' · 当前')}<span class="muted">${t.archived?'已保存':'待保存'} · ${t.versions.length} 个历史版本</span></div>${t.versions.map(v=>`<div class="version-row"><div><b>V${v.version}</b><p class="muted">${esc(v.reason)}</p></div><div class="row">${button('查看差异','compare','small',false,`data-version="${v.version}"`)}${button('恢复为新版本','restore','small',false,`data-version="${v.version}"`)}</div></div>`).join('')||'<p class="muted">本任务还没有历史版本。</p>'}${compareVersion?compare(t,compareVersion):''}<div class="actions">${button(t.invalid?'恢复有效':'标记失效','toggle-invalid','small',!t.archived)}</div>`);}

function archives(){return `<div class="strip"><span>共 ${tasks.length} 个任务</span><span class="muted">含草稿、受阻任务与已保存方案 · 复用会重新检查本次条件</span></div><div class="archive-list">${tasks.slice().reverse().map(taskCard).join('')||'<div class="panel empty">暂无策略档案。完成一条任务后在这里继续使用。</div>'}</div>`;}
function exportFile(t,type){if(type==='csv'){if(!t.result||t.result.version!==t.version)throw Error('无当前有效人群结果');download('demo-audience-'+t.id+'.csv','demo_user_id,task_version\n'+t.result.sampleIds.map(x=>x+','+t.version).join('\n'),'text/csv');}else download('demo-plan-'+t.id+'-v'+t.version+'.json',JSON.stringify({demo:true,productionExecution:false,...t},null,2),'application/json');}
function download(name,text,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function fileInput(input){const target=current();const list=[];for(const f of input.files){if(f.size>2*1024*1024){message='单份演示材料请小于 2MB';continue;}const text=/\.(md|txt)$/i.test(f.name)?await f.text():null;list.push({name:f.name,note:text?'已读取文本，需人工确认引用':'已记录文件名，未接入图片/PDF解析',text});}if(view==='task'&&target){target.materials.push(...list);E.log(target,'补充材料；未自动改写条件');}else upload.push(...list);persist();render();}
function bind(){host.querySelector('#aud-query')?.addEventListener('input',e=>{draftQuery=e.target.value;const submit=host.querySelector('[data-action=create]');if(submit)submit.disabled=!draftQuery.trim();});host.querySelector('#aud-query')?.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&!e.isComposing){e.preventDefault();if(e.target.value.trim())dispatch('create',{});}});host.querySelector('#create-platform')?.addEventListener('input',e=>draftPlatform=e.target.value);host.querySelector('.aud-attach-button')?.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();host.querySelector('#aud-material')?.click();}});host.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>dispatch(b.dataset.action,b.dataset)));host.querySelectorAll('[data-field]').forEach(n=>{if(n.tagName==='INPUT')n.addEventListener('change',()=>{const t=needTask();if(t.confirmed)return;t.fields[n.dataset.field]={value:n.value,status:'待确认'};persist();});});host.querySelectorAll('[data-pick]').forEach(n=>n.addEventListener('change',()=>{const note=host.querySelector('#strategy-note')?.value;if(n.checked)picked.add(n.dataset.pick);else picked.delete(n.dataset.pick);render();if(note!==undefined)host.querySelector('#strategy-note').value=note;}));host.querySelectorAll('[data-condition-value]').forEach(n=>n.addEventListener('change',()=>{const t=needTask();t.conditions[+n.dataset.conditionValue].value=n.value;persist();render();}));host.querySelectorAll('[data-condition-group]').forEach(n=>n.addEventListener('change',()=>{const t=needTask();t.conditions[+n.dataset.conditionGroup].group=n.value;persist();render();}));host.querySelector('#aud-material')?.addEventListener('change',e=>fileInput(e.target));host.querySelector('#aud-scope')?.addEventListener('change',e=>scope=e.target.value);host.querySelector('#aud-blocker')?.addEventListener('change',e=>{const t=needTask();if(t.conditionConfirmed||t.result)E.revise(t,3,'模拟资产状态发生变化');t.blocker=e.target.value||null;E.log(t,'演示校验状态变更');persist();render();});host.querySelector('#run-failure')?.addEventListener('change',e=>runFailure=e.target.value);}
async function dispatch(action,d){try{let t=current();if(workflowBusy&&action!=='pause-workflow')throw Error('正在处理，请等待完成或先暂停');switch(action){
case 'view-artifact':artifactView=+d.stage;break;
case 'close-artifact':artifactView=null;break;
case 'pause-workflow':E.cancelActivity(t,'业务暂停；未完成操作不会标记为成功');for(const h of t.handoffs||[])if(['prepared','running'].includes(h.status))h.status='cancelled';break;
case 'resume-workflow':if(!t.confirmed)await understandFlow(t);else if(t.strategyConfirmed&&!t.result)await executeFlow(t);else if(t.result?.approved)await archiveFlow(t);else message='当前产物已准备好，请在下方继续';break;
case 'home':artifactView=null;draftQuery='';draftPlatform='';view='home';active=null;compareVersion=null;seedAsset=null;upload=[];break;
case 'archives':view='archive';break;
case 'scene':draftQuery=E.scenarios[d.key].query;host.querySelector('#aud-query').value=draftQuery;host.querySelector('[data-action=create]').disabled=false;host.querySelector('#aud-query').focus();return;
case 'clear-seed':seedAsset=null;break;
case 'execution-tab':if(host.querySelector('#review-feedback'))t.feedback=host.querySelector('#review-feedback').value;executionTab=d.tab;break;
case 'toggle-invalid':if(!t.archived)throw Error('请先保存档案');t.invalid=!t.invalid;E.log(t,t.invalid?'标记策略失效':'恢复策略有效');break;
case 'create':{const q=host.querySelector('#aud-query').value.trim();if(!q){notify('请先描述圈人需求');return;}t=E.create(q,null,scope);t.stage=0;const platform=host.querySelector('#create-platform')?.value.trim();if(platform)t.fields.platform={value:platform,status:'已明确',source:'创建任务时填写'};draftQuery='';t.materials=upload;upload=[];if(seedAsset)t.attachedAssets.push(seedAsset);tasks.push(t);active=t.id;view='task';picked=new Set(['balanced']);E.log(t,'创建演示任务，自动整理需求');await understandFlow(t);break;}
case 'resume':artifactView=null;active=d.id;view='task';picked=new Set(current().strategy?.ids||['balanced']);break;
case 'reuse':{const src=tasks.find(x=>x.id===d.id);t=E.create(src.query,src.scenario,src.scope);if(src.invalid)throw Error('该策略已失效，请新建任务');t.fields=E.clone(src.fields);t.decisions=E.clone(src.decisions||{});Object.values(t.fields).forEach(f=>f.status=f.value?'系统推断':'待确认');t.title=src.title+' · 复用';t.reuse=true;t.reusedFrom={id:src.id,version:src.version};tasks.push(t);active=t.id;view='task';E.log(t,'复用历史方案；口径、权限与时间需要重新确认');await understandFlow(t);break;}
case 'save':E.log(needTask(),'保存草稿');message='草稿已保存到当前浏览器';break;
case 'note':{const note=host.querySelector('#aud-note').value.trim();if(note){t.notes.push(note);E.log(t,'记录补充说明，条件未自动改变');}break;}
case 'confirm-field':{const n=host.querySelector('#field-'+d.field);const val=n.value.trim();if(!val)throw Error('请先填写该项');if(d.field==='window'&&(!/^\d+$/.test(val)||+val<1||+val>3650))throw Error('时间窗口请输入 1–3650 的整数天数');if(d.field==='domain'&&!['生服','跨域'].includes(val))throw Error('本演示业务域请选择生服或跨域');t.fields[d.field]={value:val,status:'已确认'};break;}
case 'na-field':t.fields[d.field]={value:'不适用（业务确认）',status:'不适用'};break;

case 'direct-definition':{const source=host.querySelector('#direct-source').value.trim();if(!source)throw Error('请记录完整定义来源');E.confirm(t);E.select(t,['direct']);t.strategy.evidence=source;t.strategy.note='业务已提供完整定义，确认人为当前演示用户';E.log(t,'记录定义来源并跳过候选策略');break;}
case 'answer-choice':{const q=E.questions(t).find(q=>q.id===d.id);if(!q)throw Error('问题已更新');const value=q.choices[+d.choice];if(t.interactionVersion===2)E.answer(t,d.id,value);else t.fields[d.id]={value,status:'已确认'};if(!E.questions(t).length)await understandFlow(t);break;}
case 'answer-custom':{const value=host.querySelector('#answer-'+d.id).value.trim();if(!value)throw Error('请填写具体口径');if(t.interactionVersion===2)E.answer(t,d.id,value);else t.fields[d.id]={value,status:'已确认'};if(!E.questions(t).length)await understandFlow(t);break;}
case 'reopen-decision':if(t.confirmed)throw Error('请先修改需求');delete t.decisions[d.id];if(d.id==='window')t.fields.window={value:'',status:'待补充'};break;
case 'update-query':{const q=host.querySelector('#edit-query').value.trim();if(!q)throw Error('请输入需求');const next=E.create(q,null,t.scope);E.revise(t,1,'更新业务原话');for(const k of ['query','scenario','title','type','fields','decisions','interactionVersion'])t[k]=next[k];await understandFlow(t);break;}
case 'check-and-execute':{if(t.blocker||!t.confirmed||!t.strategyConfirmed||!t.conditions.length||t.conditions.some(c=>!c.value.trim()||c.permission!=='演示可用'))throw Error('存在未解决的执行缺口');const ref=host.querySelector('#seed-ref').value.trim();if(ref&&!/^DEMO-/.test(ref))throw Error('演示种子引用须以 DEMO- 开头');t.seedRef=ref;t.conditionConfirmed=true;if(!E.executable(t)){t.conditionConfirmed=false;throw Error('数据范围不符合当前入口');}E.log(t,'模拟系统检查通过，进入执行评估');t.stage=4;await executeFlow(t);break;}
case 'confirm-need':await understandFlow(t);break;
case 'analysis-convert':{const value=host.querySelector('#analysis-conclusion').value.trim();if(!value)throw Error('请提供已有分析结论与目标人群');t.type='分析转圈人';t.notes.push(value);t.fields.object={value,status:'待确认'};E.log(t,'已有结论进入需求确认，未自动开展分析');break;}
case 'copy-route':await navigator.clipboard.writeText(t.query+'\n任务类型：'+t.type+'\n当前需转交对应负责人');message='已复制需求摘要';break;
case 'confirm-strategy':{const note=host.querySelector('#strategy-note')?.value||'';const fail=host.querySelector('#strategy-failure')?.value||'';t.blocker=fail==='permission'?'permission':null;runFailure=fail==='sql'?'sql':'';await executeFlow(t,true);if(t.strategy)t.strategy.note=note;break;}
case 'revise-need':E.revise(t,1,'修改需求');await operate(t,'圈人 Agent 正在准备需求调整',[{title:'保留原有方案与结果快照',work:()=> '原版本已保留；请在下方修改业务原话，再重新生成本次方案'}]);break;
case 'revise-strategy':E.revise(t,2,'修改策略');picked=new Set(t.strategy?.ids||['balanced']);await operate(t,'圈人 Agent 正在准备策略调整',[{title:'保存历史版本并使旧结果失效',work:()=> '历史结果已保留，当前候选等待重新选择'}]);break;
case 'revise-condition':E.revise(t,3,'修改执行条件');await operate(t,'圈人 Agent 正在准备条件调整',[{title:'标记当前结果待重算',work:()=> '保留原有结果与执行回执；条件修改后须重新校验与执行'}]);break;
case 'confirm-condition':if(t.blocker||t.conditions.some(c=>!c.value.trim()))throw Error('请先补齐核心条件与缺口');t.seedRef=host.querySelector('#seed-ref').value;if(t.seedRef&&!/^DEMO-/.test(t.seedRef))throw Error('演示种子引用须以 DEMO- 开头，请勿使用真实 UID');t.conditionConfirmed=true;E.log(t,'执行条件单已确认');break;
case 'resolve':E.revise(t,3,'模拟缺口解决，重新核验条件');t.blocker=null;message='仅恢复模拟状态，未修改真实权限';await executeFlow(t);break;
case 'to-execute':if(!E.executable(t))throw Error('条件未通过校验');t.stage=4;break;
case 'back-condition':t.stage=3;break;
case 'run':await executeFlow(t);break;
case 'approve':t.feedback=host.querySelector('#review-feedback').value;await operate(t,'圈人 Agent 正在整理复核结论',[{title:'记录业务复核意见',work:()=>{E.approve(t);return '本次结果复核通过，保留业务反馈';}},{title:'整理关联产物',artifact:4,work:()=> '准备将当前版本与执行回执保存为策略资产；效果状态仍为待验证'}]);break;
case 'archive':if(!t.result?.approved)throw Error('请先通过结果复核');t.title=host.querySelector('#archive-title').value.trim()||t.title;t.adoption=host.querySelector('#adoption').value;t.destination=host.querySelector('#destination').value;await archiveFlow(t);message='已保存策略档案、执行回执与过程摘要';break;
case 'copy-sql':if(!t.result)throw Error('请先执行');await navigator.clipboard.writeText(t.result.sql);message='已复制示例 SQL，不可用于生产';break;
case 'export-csv':exportFile(t,'csv');message='已导出 3 条 DEMO 标识样例，不含真实 UID';break;
case 'report':exportFile(t,'json');message='已下载带版本的演示档案';break;
case 'step':{const step=+d.step;if(step===2&&!t.confirmed)throw Error('需求尚未确认');if(step===3&&!t.strategyConfirmed)throw Error('策略尚未确认');if(step===4&&!E.executable(t))throw Error('条件尚未通过');if(step===5&&!t.result?.approved)throw Error('结果尚未复核');t.stage=step;break;}
case 'compare':compareVersion=+d.version;break;
case 'restore':E.restore(t,+d.version);compareVersion=null;await understandFlow(t);break;
case 'portal':if(options.onPortal)options.onPortal();else location.href='https://utup-mvp-frontend.vercel.app/#myperm';return;
}persist();render();if(['create','resume','reuse','confirm-need','confirm-strategy','to-execute','approve','step','home','archives','direct-definition','check-and-execute','update-query','revise-need','revise-strategy','revise-condition','restore'].includes(action)){host.scrollIntoView({block:'start'});}}catch(e){running=false;notify(e.message||'操作失败，请重试');}}
window.AudienceWorkspace={mount,unmount(){if(workflowBusy&&current())E.cancelActivity(current(),'已离开工作区，未完成操作暂停');persist();host=null;options={};},openAsset(asset){seedAsset=asset?{id:String(asset.id),name:asset.name}:null;active=null;upload=[];view='home';render();},show(viewName){view=viewName;render();}};
})();
